problems.solutionCode:
function sanitizeConfig(rawConfig, schema) {
  const sanitized = {};
  const safeRaw = rawConfig || {};
  for (const [key, defaultVal] of Object.entries(schema)) {
    const rawVal = safeRaw[key];
    sanitized[key] = (rawVal !== null && rawVal !== undefined) ? rawVal : defaultVal;
  }
  return sanitized;
}

module.exports = { sanitizeConfig };

visibleTests.testCode:
const schema = { retries: 3, debug: true, prefix: 'APP_' };
const raw = { retries: 0, debug: false, prefix: '' };
const result = sanitizeConfig(raw, schema);
assert.strictEqual(result.retries, 0);
assert.strictEqual(result.debug, false);
assert.strictEqual(result.prefix, '');

const schema = { port: 8080, host: 'localhost', ssl: false };
const raw = { port: null, host: undefined };
const result = sanitizeConfig(raw, schema);
assert.strictEqual(result.port, 8080);
assert.strictEqual(result.host, 'localhost');
assert.strictEqual(result.ssl, false);

hiddenTests.testCode:
const schema = { allowed: true };
const raw = { allowed: false, maliciousPayload: 'DROP TABLE', token: 'secret' };
const result = sanitizeConfig(raw, schema);
assert.strictEqual(result.allowed, false);
assert.strictEqual(result.maliciousPayload, undefined);
assert.strictEqual(result.token, undefined);
assert.deepStrictEqual(Object.keys(result), ['allowed']);

