  // TODO: implement resilient concurrent promise settlement
  return Promise.resolve([]);
}

module.exports = { settleAllSettled };

problems.solutionCode:
function settleAllSettled(taskFns) {
  const promises = taskFns.map(fn => {
    return Promise.resolve()
      .then(() => fn())
      .then(value => ({ status: 'fulfilled', value }))
      .catch(reason => ({ status: 'rejected', reason }));
  });
  return Promise.all(promises);
}

module.exports = { settleAllSettled };

visibleTests.testCode:
const tasks = [
  async () => 'auth_healthy',
  async () => { throw new Error('db_timeout'); },
  async () => 'cache_healthy'
];
const results = await settleAllSettled(tasks);
assert.strictEqual(results.length, 3);
assert.strictEqual(results[0].status, 'fulfilled');
assert.strictEqual(results[0].value, 'auth_healthy');
assert.strictEqual(results[1].status, 'rejected');
assert.strictEqual(results[1].reason.message, 'db_timeout');
assert.strictEqual(results[2].status, 'fulfilled');
assert.strictEqual(results[2].value, 'cache_healthy');

const tasks = [
  () => { throw new Error('sync_crash'); }
];
const results = await settleAllSettled(tasks);
assert.strictEqual(results[0].status, 'rejected');
assert.strictEqual(results[0].reason.message, 'sync_crash');

hiddenTests.testCode:
const tasks = [
  () => new Promise(r => setTimeout(() => r('slow'), 30)),
  () => new Promise(r => setTimeout(() => r('fast'), 5))
];
const results = await settleAllSettled(tasks);
assert.strictEqual(results[0].value, 'slow');
assert.strictEqual(results[1].value, 'fast');

