problems.solutionCode:
function createPaymentStateMachine(options = {}) {
  let status = 'INITIAL';
  let orderId = null;
  let amount = null;

  return {
    dispatch(action) {
      if (!action || !action.type) throw new Error('INVALID_ACTION');

      if (status === 'INITIAL') {
        if (action.type === 'AUTHORIZE') {
          status = 'AUTHORIZED';
          orderId = action.orderId;
          amount = action.amount;
          return;
        }
        throw new Error('INVALID_STATE_TRANSITION');
      }

      if (status === 'AUTHORIZED') {
        if (action.type === 'CAPTURE') {
          status = 'SETTLED';
          return;
        }
        if (action.type === 'VOID') {
          status = 'VOIDED';
          return;
        }
        throw new Error('INVALID_STATE_TRANSITION');
      }

      // Terminal states SETTLED or VOIDED
      throw new Error('INVALID_STATE_TRANSITION');
    },

    getState() {
      return { status, orderId, amount };
    }
  };
}

module.exports = { createPaymentStateMachine };

visibleTests.testCode:
const fsm = createPaymentStateMachine();
assert.strictEqual(fsm.getState().status, 'INITIAL');
fsm.dispatch({ type: 'AUTHORIZE', orderId: 'ord-101', amount: 250 });
assert.strictEqual(fsm.getState().status, 'AUTHORIZED');
assert.strictEqual(fsm.getState().amount, 250);
fsm.dispatch({ type: 'CAPTURE' });
assert.strictEqual(fsm.getState().status, 'SETTLED');

const fsm = createPaymentStateMachine();
assert.throws(() => fsm.dispatch({ type: 'CAPTURE' }), /INVALID_STATE_TRANSITION/);
fsm.dispatch({ type: 'AUTHORIZE', orderId: 'ord-102', amount: 50 });
fsm.dispatch({ type: 'VOID' });
assert.strictEqual(fsm.getState().status, 'VOIDED');
assert.throws(() => fsm.dispatch({ type: 'CAPTURE' }), /INVALID_STATE_TRANSITION/);

hiddenTests.testCode:
const fsm = createPaymentStateMachine();
fsm.dispatch({ type: 'AUTHORIZE', orderId: 'ord-103', amount: 99 });
assert.throws(() => fsm.dispatch({ type: 'UNKNOWN_OP' }), /INVALID_STATE_TRANSITION/);
assert.strictEqual(fsm.getState().status, 'AUTHORIZED');
